<?php
declare(strict_types=1);
require_once __DIR__.'/inc/auth.php';require_once __DIR__.'/inc/region.php';
cs_security_headers();header('Cache-Control: no-store, private');
if(!cs_authed()){header('Location: admin.php');exit;}
$errors=[];$notice='';
if(isset($_GET['status'])){header('Content-Type: application/json; charset=utf-8');echo json_encode(cs_region_status());exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!cs_verify_csrf())$errors[]='Sessie verlopen. Vernieuw de pagina.';
 else {
  $action=$_POST['action']??'save';
  if(!cs_region_save($_POST,$errors))$errors[]='Opslaan mislukt.';
  elseif(!$errors){
    if($action==='save'){$notice='Regioagenda opgeslagen. De tekst voor beide edities is automatisch bijgewerkt.';}
    else{
      $eds=$action==='both'?[1,2]:[$action==='edition2'?2:1];
      foreach($eds as $ed){[$ok,$message]=cs_region_dispatch($ed);if($ok)$notice.=$message.' ';else $errors[]=$message;}
    }
  }
 }
}
$d=cs_region_load();$api=cs_api_available();$repo=cs_region_repo();
